import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  // ================= LOAD DATA =================
  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");
      setData(res.data);
      setLoading(false);
    } catch (err) {
      console.log("ERROR API:", err);
      setLoading(false);
    }
  };

  const latest = data.length > 0 ? data[0] : {};

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "red";
    if (kondisi === "PERINGATAN") return "orange";
    return "#22c55e";
  };

  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e"
      }
    ]
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#0f172a", color: "white" }}>

      {/* SIDEBAR */}
      <div style={{ width: 220, background: "#1e293b", padding: 20 }}>
        <h2>⚡ Hematrik</h2>
        <p style={{ cursor: "pointer" }} onClick={() => setPage("dashboard")}>Dashboard</p>
        <p style={{ cursor: "pointer" }} onClick={() => setPage("monitoring")}>Monitoring</p>
        <p style={{ cursor: "pointer" }} onClick={() => setPage("history")}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 30 }}>

        {loading && <h2>Loading...</h2>}

        {/* DASHBOARD */}
        {page === "dashboard" && data.length > 0 && (
          <>
            <h1>📊 Dashboard Monitoring</h1>

            <div style={{
              padding: 15,
              borderRadius: 10,
              background: getColor(latest.kondisi)
            }}>
              {latest.notifikasi}
            </div>

            <div style={{ display: "flex", gap: 20, marginTop: 20 }}>
              <div style={card}><h3>People</h3><h1>{latest.jumlah_orang}</h1></div>
              <div style={card}><h3>Listrik</h3><h1>{latest.status_listrik}</h1></div>
              <div style={card}>
                <h3>Kondisi</h3>
                <h1 style={{ color: getColor(latest.kondisi) }}>
                  {latest.kondisi}
                </h1>
              </div>
            </div>

            <div style={{ marginTop: 30 }}>
              <Line data={chartData} />
            </div>
          </>
        )}

        {/* MONITORING (FIX FINAL) */}
        {page === "monitoring" && (
          <>
            <h1>📷 CCTV AI Monitoring</h1>

            <div style={{ marginTop: 20 }}>
              <img
                src="http://127.0.0.1:8000/stream"
                alt="CCTV"
                style={{
                  width: "700px",
                  borderRadius: "12px",
                  border: "2px solid #1e293b"
                }}
              />
            </div>

            <p style={{ marginTop: 20 }}>🔴 Live Detection Active</p>
          </>
        )}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1>📜 History</h1>

            <table style={{ width: "100%", marginTop: 20 }}>
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>

              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getColor(d.kondisi) }}>
                      {d.kondisi}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

const card = {
  background: "#1e293b",
  padding: 20,
  borderRadius: 10
};

export default App;
